-- Feature the curated subset of real companies that correspond to the
-- public marketing site's former hardcoded COS showcase array.
-- Only sets featured=1 on these 63 specific rows; touches no other data
-- in the existing companies table.
UPDATE companies SET featured = 1 WHERE id IN (2817,2552,1219,2356,3198,469,3095,2575,3054,350,849,848,973,1050,476,1060,831,1042,2736,2777,403,1085,3049,850,3222,2134,2272,164,54,2516,874,839,3324,3300,2850,2774,572,1033,636,1162,2886,3498,846,845,844,884,305,3329,2202,27,2526,2686,3124,3164,1155,1004,1003,618,883,1126,12,2569,1908);

-- Maps the old hardcoded COS ids (still referenced by RESP/PD/CANNED_RESULTS
-- in index.html) to the real companies table ids, and carries the demo-only
-- presentational fields (logo/color/score/caps/regions/sites/etc.) that have
-- no equivalent column in the real companies table -- these were always
-- illustrative showcase flourishes, not real data, so they're kept as-is
-- rather than invented fresh for the real dataset.
DROP TABLE IF EXISTS featured_id_map;
CREATE TABLE featured_id_map (
  cos_id INTEGER PRIMARY KEY,
  company_id INTEGER NOT NULL REFERENCES companies(id),
  type TEXT,
  logo TEXT,
  color TEXT,
  score INTEGER,
  alerts INTEGER DEFAULT 0,
  alert_url TEXT,
  alert_info TEXT,
  upd TEXT,
  partner_type TEXT,
  caps TEXT,
  regions TEXT,
  sites TEXT
);

